console.log(null == undefined);  // true
console.log(null === undefined); // false
console.log(typeof null);          // "object" — bug
console.log(typeof undefined);     // "undefined"

function safeObject(value) {
  return value !== null && typeof value === "object";
}

const payload = { a: 1, b: undefined, c: null };
console.log(JSON.stringify(payload)); // {"a":1,"c":null}

const parsed = JSON.parse('{"a":1,"c":null}');
console.log(parsed.b); // undefined — key absent
console.log(parsed.c); // null

function greet(name = "guest") {
  return `Hello ${name}`;
}

greet(undefined); // "Hello guest" — default applies
greet(null);        // "Hello null" — null is a value

greet();            // "Hello guest"
